import numpy as np,mujoco
class Metrics:
 def __init__(self,s):
  self.s=s;self.step=s.step;self.rows=[];self.force_max=0;self.pen_max=0;self.tray_force_max=0
  s.step=self.wrapped
 def wrapped(self,a):
  result=self.step(a)
  s=self.s
  obj=s.data.xpos[s.model.body('obj_main').id].copy()
  force=0.;tray=0.;pen=0.
