   pair=tuple(ns);self.pairs[pair]=max(v,self.pairs.get(pair,0))
  self.rows.append([len(self.s.actions),total]);self.max=max(self.max,total);return result
 def finish(self,path):
  self.s.step=self.step;np.savez(path,metrics=self.rows);return self.max,self.pairs
